#ifndef EMBEDDED_H
#define EMBEDDED_H
#include "rpfs.h"

/* Programs compiled into the kernel image (generated by tools/embed.py into build/embedded.c). */
struct embedded_file { const char *path; const unsigned char *data; unsigned size; };
extern const struct embedded_file embedded_files[];
extern const unsigned embedded_count;

int embedded_install(struct rpfs *fs);       /* create /bin and copy every embedded program into it; returns the count or an error */
#endif
